var exp = metadata.ss_fg_token_exp ? parseInt(metadata.ss_fg_token_exp) : 0;
if (metadata.ss_fg_token && exp > Date.now() + 3600000) {
    return ["vigente"];
}
return ["renovar"];

// Cuerpo del POST /api/login/ con las credenciales del poller (atributos de servidor).
if (!metadata.ss_fg_username || !metadata.ss_fg_password) {
    throw new Error("Faltan los atributos de servidor fg_username / fg_password en el 4eGrowth Poller");
}
return {
    msg: { username: "" + metadata.ss_fg_username, password: "" + metadata.ss_fg_password },
    metadata: metadata,
    msgType: "POST"
};

// Respuesta de /api/login/: { access, refresh }. El access es un JWT de 7 dias.
if (!msg.access) {
    throw new Error("Login 4eGrowth sin token: " + (msg.detail || JSON.stringify(msg)));
}
var exp = Date.now() + 6 * 86400000;          // margen: se renueva a los 6 dias
try {
    var p = msg.access.split(".")[1].replace(/-/g, "+").replace(/_/g, "/");
    // decodificacion base64 sin atob (no existe en el motor JS de ThingsBoard)
    var chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    var bits = "", txt = "";
    for (var i = 0; i < p.length; i++) {
        var c = chars.indexOf(p.charAt(i));
        if (c < 0) { continue; }
        bits += ("000000" + c.toString(2)).slice(-6);
    }
    for (var j = 0; j + 8 <= bits.length; j += 8) { txt += String.fromCharCode(parseInt(bits.substr(j, 8), 2)); }
    var payload = JSON.parse(txt);
    if (payload.exp) { exp = payload.exp * 1000 - 86400000; }
} catch (e) { /* nos quedamos con el margen por defecto */ }
metadata.ss_fg_token = msg.access;
metadata.ss_fg_token_exp = "" + exp;
return {
    msg: { fg_token: msg.access, fg_token_exp: exp },
    metadata: metadata,
    msgType: "POST_ATTRIBUTES_REQUEST"
};

// Una sonda de /api/data_device/devices/:
// { key, description: "S1195", company{id,name}, farm{id,name}, parcel{id,name} }
// Prepara nombre/tipo del dispositivo y la ventana de fechas (igual que "Clasifica + ventana" de Qampo).
var dev = msg;
if (!dev || !dev.key || !dev.description) {
    throw new Error("Sonda 4eGrowth sin key/description: " + JSON.stringify(dev));
}
metadata.fg_key = "" + dev.key;
metadata.fg_codigo = "" + dev.description;
