metadata.deviceName = "4e-" + dev.description;
metadata.deviceType = "Sonda de humedad de suelo";
metadata.fg_empresa = (dev.company && dev.company.name) ? ("" + dev.company.name).trim() : "";
metadata.fg_finca = (dev.farm && dev.farm.name) ? ("" + dev.farm.name).trim() : "";
