// perder las ultimas lecturas del dia anterior, que la sonda sube con retraso.
// Un dia de una sonda pesa ~60 KB (limite de los scripts de ThingsBoard: 100 KB).
function fmt(t) {
    var d = new Date(t);
    function p(n) { return ("0" + n).slice(-2); }
    return d.getUTCFullYear() + "-" + p(d.getUTCMonth() + 1) + "-" + p(d.getUTCDate());
}
