metadata.fg_cultivo = cap(v.logo_cultivo);
var lat = parseFloat(v.latitud), lon = parseFloat(v.longitud);
metadata.fg_lat = isNaN(lat) ? "" : "" + lat;
metadata.fg_lon = isNaN(lon) ? "" : "" + lon;
if (!metadata.fg_parcel_id && msg.parcel && msg.parcel.id) { metadata.fg_parcel_id = "" + msg.parcel.id; }
return { msg: {}, metadata: metadata, msgType: msgType };

