var props = (msg && msg.properties) ? msg.properties : {};
var attrs = { fg_ficha_ts: Date.now() };
if (metadata.fg_cultivo) { attrs.cultivo = metadata.fg_cultivo; }
if (metadata.fg_lat && metadata.fg_lon) {
    attrs.latitude = parseFloat(metadata.fg_lat);
    attrs.longitude = parseFloat(metadata.fg_lon);
}
var ha = parseFloat(props.hectares);
if (!isNaN(ha)) { attrs.hectareas = (Math.round(ha * 100) / 100) + " ha"; }   // mismo formato que las demas sondas ("11.6 ha")
return { msg: attrs, metadata: metadata, msgType: "POST_ATTRIBUTES_REQUEST" };
